# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port, payload){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate, br
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0

`
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr,"payload":payload}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    if len(rsp) > 0 {
        if str.MatchAllOfRegexp(rsp, `<username>(.*)</username>`) && str.MatchAllOfSubString(rsp, "HTTP/1.1 200") {
            yakit.Info("%v MessageSolution CNVD-2021-10543邮件归档系统EEA 信息泄露漏洞", addr)
            risk.NewRisk(
            addr,risk.title("MessageSolution CNVD-2021-10543邮件归档系统EEA 信息泄露漏洞"),
            risk.severity("high"),
            risk.titleVerbose("MessageSolution CNVD-2021-10543邮件归档系统EEA 信息泄露漏洞存在"),
            risk.type("文件读取[Alibaba]"),
            risk.request(string(req)),
            risk.response(string(rsp)),
        )
        }else{
            println("不存在MessageSolution CNVD-2021-10543邮件归档系统EEA 信息泄露漏洞")
            }
       
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    payload = `/authenticationserverservlet/`

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port, payload)
    }
    
}
